describe('UserService', () => {
    describe('createUser', () => {
        it('should create a user with valid data', async () => {
            // Arrange: Set up test data and dependencies
            const userData = {
                email: 'test@example.com',
                name: 'John Doe'
            };
            const mockRepository = {
                save: jest.fn().mockResolvedValue({ id: '123', ...userData })
            };
