        it('should throw ValidationError for invalid email', async () => {
            // Arrange
            const userData = { email: 'invalid', name: 'John' };
            const service = new UserService({});

            // Act & Assert
            await expect(service.createUser(userData))
                .rejects
                .toThrow(ValidationError);
        });
    });
});
